        .map_err(|e| format!("prepare failed: {}", e))?;

    let mut batch = JournalWriteBatch::new(&journal);
    batch.byte_limit = Some(18);
    let result = batch.put_artifact_sequence(seq);

    assert!(matches!(
        result,
        Err(JournalError::JournalBatchBytesExceeded {
            attempted: 19,
            limit: 18
        })
    ));
